    p_quad, p_mc, p_grid = results["quad"], results["mc"], results["grid"]
    assert abs(p_quad - p_mc) < 0.005
    assert abs(p_quad - p_grid) < 0.005
    assert abs(p_mc - p_grid) < 0.005


def test_value_range(results):
    for key in ("quad", "mc", "grid"):
        assert 0.97 <= results[key] <= 0.995, f"{key}={results[key]}"


def test_expected_loss_below_threshold(results):
    assert results["expected_loss_choose_b"] < 0.0002


def test_reproducible_across_runs():
    r1 = bayes_ab.run_all()
    r2 = bayes_ab.run_all()
    assert r1 == r2


def test_posterior_params():
    assert (bayes_ab.A_ALPHA, bayes_ab.A_BETA) == (121, 2281)
    assert (bayes_ab.B_ALPHA, bayes_ab.B_BETA) == (157, 2245)


def test_summary_mentions_all_methods():
    text = bayes_ab.summarize(bayes_ab.run_all())
